export function sameValue(a,b) {
  if(a===b)return true;
  if(!a||!b||typeof a!=='object'||typeof b!=='object')return false;
  if(Array.isArray(a)||Array.isArray(b))return Array.isArray(a)&&Array.isArray(b)&&a.length===b.length&&a.every((value,index)=>sameValue(value,b[index]));
  const keys=Object.keys(a);
  return keys.length===Object.keys(b).length&&keys.every(key=>Object.prototype.hasOwnProperty.call(b,key)&&sameValue(a[key],b[key]));
}

// These fields are read-model evidence, regenerated by the backend on save/index.
// Compare JSON-persisted intent so optional undefined values match absent fields.
const graphContent=graph=>JSON.parse(JSON.stringify({...graph,nodes:graph.nodes.map(({needId,code,test,properties,...node})=>node)}));
export function sameGraph(left,right) {
  return sameValue(graphContent(left),graphContent(right));
}

// An acknowledgment owns only the submitted snapshot, never subsequent editing.
export function reconcileGraphSave(current,submitted,canonical) {
  return sameGraph(current,submitted)?structuredClone(canonical):current;
}
